import type { Account, Pane, Recording, Split, State, Step } from './contracts';
import { balancedLayout, splitPane } from './layout';
type Workspace = { id:string; name:string; createdAt:string };
type RecordingSummary = { id:string; name:string; environmentId:string; accountId:string; steps:number; createdAt:string; replayLang:string };
type ReplayView = { recordingId:string; name:string; index:number; total:number; status:'playing'|'paused'|'done'|'stopped'; speed:number; lang:string; step:{kind:Step['kind'];label:string}|null; error?:ReplayFailure; picking:'web'|'mobile'|null; waiting:Waiting[]; log:LogEntry[]; detail:StepDetail|null; stale:boolean; web:string; mobile:string; device:{name:string;width:number;height:number} };
type Recorded = { tag?:string; html?:string; text?:string; dialog?:string; pos?:string };
type Waiting = { target:'web'|'mobile'; state:string; selector?:string; coveredBy?:string; since:number };
type LogEntry = { index:number; target:'web'|'mobile'; kind:Step['kind']; label:string; ms:number; outcome:'ok'|'noop'|'skipped'|'failed'; code?:string; selector?:string; note?:string };
type StepDetail = { selectors:string[]; target?:Recorded; optional:boolean; fragile:boolean; mobilePre:number };
type Diagnosis = { url:string; title:string; dialog:string; focus:string; selectors:{ selector:string; matches:number; visible:number; problem:string; coveredBy:string }[] };
type ReplayFailure = { index:number; target:'web'|'mobile'; code:string; step:{kind:Step['kind'];label:string}; at:string; report?:string; failures:{ target:'web'|'mobile'; code:string; message:string; hint:string; detail?:string; diagnosis?:Diagnosis; menuTried?:boolean; waitedMs?:number; trace?:{ms:number;state:string;selector?:string;coveredBy?:string}[]; recorded?:Recorded }[] };
type AppState = State & { panes: Pane[]; credentials: { accountId:string; configured:boolean;revision:number }[]; agentEnabled:boolean; workspaces:{ active:string; list:Workspace[] }; recordings: RecordingSummary[]; recording: { paneId:string; recordingId:string; steps:number; startedAt:number }|null; replay: ReplayView|null; build:{ stale:boolean; startedAt:string } };
type Edge = 'bottom'|'top'|'left'|'right';
declare global { interface Window { hostframe: { command:(c:string,p?:unknown)=>Promise<any>;desktop:(c:string,p?:unknown)=>Promise<any>;bounds:(v:unknown)=>void;frames:(fn:(f:Record<string,string>)=>void)=>void;subscribe:(fn:(s:AppState)=>void)=>void } } }
let state: AppState;
let environmentId='local', focusId='', layout: Split|null=null, layoutCustom=false, dragging=false, dockDragging=false;
const $=(id:string)=>document.getElementById(id)!;
const dialog=$('dialog') as HTMLDialogElement;
const pop=$('pop');
const escape=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const ROLE_COLORS: Record<string,string>={owner:'#4f5bd5',driver:'#1d9a8a',intaker:'#d98b1c',dispatcher:'#d9546f',billing:'#8a5cd6',manager:'#2e8fd4'};
const PALETTE=['#4f5bd5','#1d9a8a','#d98b1c','#d9546f','#8a5cd6','#2e8fd4','#5c8a3a','#b9622f'];
